app.use(authenticate);         // 1) 누구인가 — req.user 를 채운다

app.get('/orders/:id', async (req, res) => {
  const order = await db.order.findFirst({
    where: { id: req.params.id, userId: req.user.id },   // 2) 인가 — 소유 확인
  });
  if (!order) return res.status(404).end();
  res.json(order);
});

import argon2 from 'argon2';

// 가입
const hash = await argon2.hash(password);        // 솔트·비용이 값 안에 들어간다

// 로그인
const ok = await argon2.verify(hash, password);

// 타이밍 공격 방지 — 계정이 없어도 같은 시간을 쓴다
const user = await findUser(email);
const valid = user ? await argon2.verify(user.hash, password) : await argon2.hash('dummy');
if (!user || !valid) return res.status(401).json({ error: '이메일 또는 비밀번호가 올바르지 않습니다' });

// 웹 앱 — 세션 쿠키 (앞 칸 5장의 세 속성)
Set-Cookie: sid=…; HttpOnly; Secure; SameSite=Lax; Path=/

// SPA·모바일에서 토큰을 쓴다면
//  · localStorage 는 XSS 에 그대로 노출된다
//  · 되도록 HttpOnly 쿠키 · 아니면 메모리에만 두고 갱신은 쿠키로

// 로그아웃은 서버에서 무효화한다
await sessions.delete(sid);          // 세션
await refreshTokens.revoke(userId);  // 토큰 방식이면 갱신 토큰을 폐기

jwt.verify(token, publicKey, {
  algorithms: ['RS256'],        // 허용 알고리즘을 못 박는다 (none·혼동 공격 방지)
  issuer: 'https://auth.example.com',
  audience: 'api.example.com',
  clockTolerance: 5,            // 시계 오차 허용치
});
// exp 검증은 대부분 라이브러리가 기본으로 한다 — 끄지 마라

// 흩어진 형태 — 하나를 빠뜨리면 열린다
if (user.role === 'admin' || order.userId === user.id) { … }

// 모은 형태 — 규칙에 이름을 준다
const can = (user, action, resource) => policy[action]?.(user, resource) ?? false;

const policy = {
  'order:read':  (u, o) => o.userId === u.id || u.role === 'admin',
  'order:refund': (u, o) => u.role === 'admin' && o.status === 'paid',
};

if (!can(req.user, 'order:refund', order)) return res.status(403).end();
